css:
.print-format { padding: 0; color:#1f2937; font-family:"Helvetica Neue",Helvetica,Arial,sans-serif; font-size:11px; }
* { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; }
.f16 { padding: 6mm 7mm; }
.f16 h2 { font-size:15px; font-weight:700; text-align:center; margin:0; color:#111827; }
.f16 .sub { text-align:center; font-size:10px; color:#6b7280; margin:2px 0 10px; }
.f16 .rule { height:3px; background:#1f2937; border:0; margin:6px 0 12px; }
.f16 .sec { font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:#1f2937; margin:14px 0 6px; padding-bottom:3px; border-bottom:2px solid #1f2937; }
.f16 table { width:100%; border-collapse:collapse; }
.kv td { padding:4px 8px; border:1px solid #e5e7eb; vertical-align:top; }
.kv .k { background:#f9fafb; color:#6b7280; font-weight:600; width:18%; }
.kv .v { font-weight:600; color:#111827; width:32%; }
.partb td { padding:5px 10px; border-bottom:1px solid #eceef1; }
.partb td.amt { text-align:right; font-variant-numeric:tabular-nums; }
.partb tr:nth-child(even) td { background:#fafafb; }
.partb .strong td { font-weight:700; color:#111827; background:#f3f4f6 !important; border-top:1px solid #1f2937; }
.grid th { background:#1f2937; color:#fff; font-size:9px; text-transform:uppercase; padding:6px 8px; text-align:left; }
.grid td { padding:5px 8px; border-bottom:1px solid #eceef1; }
.grid td.amt, .grid th.amt { text-align:right; }
.f16 .foot { margin-top:18px; font-size:10px; color:#374151; }
.f16 .sign { margin-top:28px; display:block; }
